aside.limit { border-left: 4px solid var(--note-rule); background: var(--note-bg); border-radius: 0 6px 6px 0;
  padding: 10px 14px; margin: 0 0 .9rem; font-size: .94rem; }
aside.limit .label { color: var(--muted); }
